class Solution {
    public String tree2str(TreeNode root) {
        StringBuilder builder = new StringBuilder();
        appendPreorder(root, builder);
        return builder.toString();
    }

    private void appendPreorder(TreeNode node, StringBuilder builder) {
        if (node == null) {
            return;
        }
        builder.append(node.val);
        if (node.left != null || node.right != null) {
            builder.append('(');
            appendPreorder(node.left, builder);
            builder.append(')');
        }
        if (node.right != null) {
            builder.append('(');
            appendPreorder(node.right, builder);
            builder.append(')');
        }
    }
}

class Solution {
    public String tree2str(TreeNode root) {
        if (root == null) {
            return "";
        }
        String value = String.valueOf(root.val);
        if (root.left == null && root.right == null) {
            return value;
        }
        if (root.right == null) {
            return value + "(" + tree2str(root.left) + ")";
        }
        return value + "(" + tree2str(root.left) + ")(" + tree2str(root.right) + ")";
    }
}

class Solution {
    public String tree2str(TreeNode root) {
        if (root == null) {
            return "";
        }

        class Frame {
            TreeNode node;
            char token;

            Frame(TreeNode node) {
                this.node = node;
            }

            Frame(char token) {
                this.token = token;
            }
        }

        StringBuilder builder = new StringBuilder();
        java.util.Deque<Frame> stack = new java.util.ArrayDeque<>();
        stack.push(new Frame(root));
        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            if (frame.node == null) {
                builder.append(frame.token);
                continue;
            }

            TreeNode node = frame.node;
            builder.append(node.val);
            if (node.right != null) {
                stack.push(new Frame(')'));
                stack.push(new Frame(node.right));
                stack.push(new Frame('('));
            }
            if (node.left != null || node.right != null) {
                stack.push(new Frame(')'));
                if (node.left != null) {
                    stack.push(new Frame(node.left));
                }
                stack.push(new Frame('('));
            }
        }
        return builder.toString();
    }
}
